#!/usr/bin/env bash
# batch_p04_outbound_queue.sh
#
# P0.4 (G5, disasters #4/#5/#17): durable outbound send queue with
# idempotency, pacing, per-number token-bucket rate limiting, and
# crash-safe recovery — plus the WaDriver/FakeWaDriver abstraction
# (gateway/src/driver/, gateway/test-support/) that closes OQ-7, since
# P0.4's own official acceptance text requires FakeWa explicitly.
#
# This script only WRITES files and RUNS verification (hunt_gate + the full
# real-Redis test suite, including the official P0.4 chaos acceptance test:
# 50 messages, 5x real `kill -9` + restart, zero loss). It does NOT run
# `git add`/`git commit` — review the diff yourself, then commit separately.
#
# Run from the repository root: /home/sharwa/sharwa_ai
set -euo pipefail

REPO_ROOT="/home/sharwa/sharwa_ai"
if [ ! -d "$REPO_ROOT/gateway" ]; then
  echo "ERROR: $REPO_ROOT/gateway not found. Run this script from a machine where the repo lives at $REPO_ROOT, or edit REPO_ROOT at the top of this script." >&2
  exit 1
fi
cd "$REPO_ROOT"

echo "=== [0/6] Pre-flight: repo root = $REPO_ROOT ==="
git rev-parse --is-inside-work-tree >/dev/null 2>&1 && echo "  git repo: OK" || { echo "ERROR: not a git repository" >&2; exit 1; }

echo ""
echo "=== [1/6] Writing P0.4 files (base64-embedded, decoded in place) ==="

write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path.b64.tmp"
  base64 -d "$path.b64.tmp" > "$path"
  rm -f "$path.b64.tmp"
  echo "  wrote: $path ($(wc -c < "$path") bytes)"
}

