echo ""
echo "=== [2/6] gateway/.dockerignore now excludes test-support/ (H7 double-gate fix, see docs/P0_DEVIATIONS.md D-18) ==="
grep -n "test-support" gateway/.dockerignore || { echo "ERROR: test-support line missing from .dockerignore" >&2; exit 1; }

echo ""
echo "=== [3/6] Syntax-check every new/modified JS file ==="
for f in \
  gateway/src/config.js \
  gateway/src/sessions.js \
  gateway/src/index.js \
  gateway/src/driver/waDriver.js \
  gateway/test-support/fakeWaDriver.js \
  gateway/src/outbound/queue.js \
  gateway/src/outbound/tokenBucket.js \
  gateway/src/__tests__/webhook.test.js \
  gateway/src/__tests__/tokenBucket.test.js \
  gateway/src/__tests__/outbound_queue.test.js \
  gateway/src/__tests__/outbound_chaos.test.js \
  gateway/src/__tests__/_outbound_chaos_child.mjs \
; do
  node --check "$f" && echo "  OK: $f"
done

echo ""
echo "=== [4/6] hunt_gate (static discipline check) ==="
if command -v node >/dev/null 2>&1 && [ -f scripts/hunt_gate.mjs ]; then
  node scripts/hunt_gate.mjs || echo "  (hunt_gate reported violations above — review them; prior phases showed only non-fatal scratch-script violations, but check this run's output yourself)"
else
  echo "  SKIPPED: node or scripts/hunt_gate.mjs not found on PATH/repo — run it manually and review before committing."
fi

echo ""
echo "=== [5/6] Full real-Redis test suite (85 pre-existing + 11 new P0.4 tests = 96), via the live redis-durable stack ==="
echo "    (No standalone redis-server binary exists on this VPS — Redis only runs via Docker here, same as every other"
echo "     real-Redis suite in this project; see real_redis_integration.test.js's own header comment for the precedent"
echo "     this reuses verbatim: docker compose run --rm ... gateway node --test ...)"
echo ""
echo "    This runs against the SAME real redis-durable the live gateway uses. All P0.4 test keys use randomized"
echo "    session/destination ids (crypto.randomUUID()) so nothing collides with real session data, and nothing is"
echo "    flushed — same precedent as real_redis_integration.test.js."
echo ""

if ! command -v docker >/dev/null 2>&1; then
  echo "ERROR: docker not found — cannot run the real-Redis test suite. Install docker or run the tests manually against a real redis-durable." >&2
  exit 1
fi

DC="docker compose"
$DC version >/dev/null 2>&1 || DC="docker-compose"

echo "--- running full suite (src/__tests__/*.test.js) ---"
$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  gateway node --test "src/__tests__/*.test.js"

echo ""
echo "--- running the P0.4 chaos acceptance test again on its own, for a clean, isolated result ---"
echo "    (spec: 50 queued messages -> kill -9 the gateway mid-way x5 -> restart -> all 50 reach FakeWa with zero loss;"
echo "     duplicate count measured and printed, bounded by the number of kills)"
$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  gateway node --test src/__tests__/outbound_chaos.test.js

echo ""
echo "=== [6/6] Review: git status / diff --stat (NO commit performed by this script) ==="
git status --short
echo ""
git diff --stat -- gateway/src gateway/test-support gateway/.env.example gateway/.dockerignore docs/P0_DEVIATIONS.md docs/P0_OPEN_QUESTIONS.md docs/P0_FINDINGS.md || true

echo ""
echo "=== Done. Nothing was committed. Review the diff above, then commit yourself when satisfied. ==="
echo "New files this phase closes OQ-7 (FakeWaDriver) — see docs/P0_OPEN_QUESTIONS.md and docs/P0_DEVIATIONS.md (D-18)."
